import{_ as t,o as n,c as a,ai as o}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"关于我","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),i={name:"about/index.md"};function l(s,r,e,g,d,c){return n(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to “关于我”">​</a></h1><h2 id="我为什么做这个网站" tabindex="-1">我为什么做这个网站？ <a class="header-anchor" href="#我为什么做这个网站" aria-label="Permalink to “我为什么做这个网站？”">​</a></h2><p><strong>最核心的目标：通过输出倒逼输入，把学习变成可复用的长期资产。</strong></p><p>这个网站是我的 <strong>Second Brain（第二大脑）</strong>。不限于开发，后续会把各个方面的学习总结都汇总到这里，例如：</p><ul><li>💻 <strong>开发与技术</strong>：Java、数据库、框架、工业数字化等</li><li>📝 <strong>求职笔记</strong>：面向求职的系统整理</li><li>🤖 <strong>AI</strong>：大模型、Agent、工具链与项目实践</li><li>🌱 <strong>运动健身</strong>：睡眠、训练计划、久坐与肩颈等</li><li>💰 <strong>财务</strong>：记账、应急金、理财认知等</li><li>🗣️ <strong>语言与表达</strong>：英语口语等</li></ul><p>通过系统整理和输出，我希望自己能够：</p><ul><li>📝 <strong>加深理解</strong>：写出来，才算真正学进去</li><li>🎯 <strong>建立体系</strong>：把零散知识点串成完整框架</li><li>🔄 <strong>持续迭代</strong>：随着学习深入不断更新，留下成长轨迹</li><li>💡 <strong>发现盲区</strong>：整理时暴露不会的地方，明确下一步方向</li></ul><h2 id="次要目标-知识分享" tabindex="-1">次要目标：知识分享 <a class="header-anchor" href="#次要目标-知识分享" aria-label="Permalink to “次要目标：知识分享”">​</a></h2><p>在自我学习的同时，我也希望这些内容能够：</p><ul><li>🌱 帮到同样在学习的人</li><li>📚 提供一条可参考的学习路径</li><li>🤝 方便交流，互相纠错与补充</li></ul><h2 id="当前已有内容" tabindex="-1">当前已有内容 <a class="header-anchor" href="#当前已有内容" aria-label="Permalink to “当前已有内容”">​</a></h2><p>✓ <strong>求职笔记</strong>：Java / 数据库 / 框架 / 面试准备等<br> ✓ <strong>技术</strong>：技术体系与工业数字化<br> ✓ <strong>AI 探索</strong><br> ✓ <strong>生活</strong>：英语口语 / 运动健身 / 财务（运动健身与财务目前为示例骨架）<br> ✓ <strong>项目与资源</strong></p><p>后续会把 Second Brain 项目与本站整合，让笔记、体系和站点形成闭环。</p><h2 id="我的学习方式" tabindex="-1">我的学习方式 <a class="header-anchor" href="#我的学习方式" aria-label="Permalink to “我的学习方式”">​</a></h2><ul><li><strong>系统化学习</strong>：按模块整理，构建完整知识体系</li><li><strong>实战驱动</strong>：结合项目与生活实践，学以致用</li><li><strong>输出倒逼输入</strong>：通过写作加深理解，发现盲区</li><li><strong>持续更新</strong>：内容会长期迭代，不追求一次写完</li></ul><hr><blockquote><p>💭 <strong>我的理念</strong>：最好的学习方式之一，就是尝试把事情讲清楚。Second Brain 是学习路上的见证，也是持续进步的动力。</p></blockquote><p>感谢你的访问。如果内容对你有帮助，我会很开心；如果发现错误或不足，也欢迎指正——那同样是我的学习机会。</p>',18)])])}const _=t(i,[["render",l]]);export{p as __pageData,_ as default};
